from copy import deepcopy


def _integer(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an integer")
    return value


def resolve_encounter(state, action):
    if not isinstance(state, dict) or not isinstance(action, dict):
        raise TypeError("state and action must be dictionaries")
    if set(state) != {"player", "targets", "score", "boosts", "ended"}:
        raise ValueError("invalid state fields")
    if set(action) != {"dx", "dy", "fire"}:
        raise ValueError("invalid action fields")

    player = state["player"]
    if not isinstance(player, dict):
        raise TypeError("player must be a dictionary")
    if set(player) != {"x", "y", "health", "lives"}:
        raise ValueError("invalid player fields")
    for key in ("x", "y", "health", "lives"):
        _integer(player[key], f"player.{key}")
    if not 0 <= player["x"] <= 9 or not 0 <= player["y"] <= 9:
        raise ValueError("player coordinates outside grid")
    if not 0 <= player["health"] <= 3:
        raise ValueError("invalid player health")
    if player["health"] == 0 and not state["ended"]:
        raise ValueError("zero health requires an ended state")
    if player["lives"] < 0:
        raise ValueError("invalid lives")

    targets = state["targets"]
    if not isinstance(targets, list):
        raise TypeError("targets must be a list")
    for target in targets:
        if not isinstance(target, dict):
            raise TypeError("each target must be a dictionary")
        if set(target) != {"x", "y", "health", "points"}:
            raise ValueError("invalid target fields")
        for key in ("x", "y", "health", "points"):
            _integer(target[key], f"target.{key}")
        if not 0 <= target["x"] <= 9 or not 0 <= target["y"] <= 9:
            raise ValueError("target coordinates outside grid")
        if target["health"] <= 0 or target["points"] <= 0:
            raise ValueError("target health and points must be positive")

    _integer(state["score"], "score")
    if state["score"] < 0:
        raise ValueError("score must be non-negative")
    if not isinstance(state["boosts"], list):
        raise TypeError("boosts must be a list")
    if any(boost not in ("heal", "double") for boost in state["boosts"]):
        raise ValueError("unknown boost")
    if type(state["ended"]) is not bool:
        raise TypeError("ended must be bool")
    if player["lives"] == 0 and not state["ended"]:
        raise ValueError("zero lives requires an ended state")

    dx = _integer(action["dx"], "dx")
    dy = _integer(action["dy"], "dy")
    if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
        raise ValueError("movement delta outside range")
    if type(action["fire"]) is not bool:
        raise TypeError("fire must be bool")

    result = state.copy()
    if result["ended"]:
        return result

    if "heal" in result["boosts"]:
        result["boosts"].remove("heal")
        result["player"]["health"] = min(3, result["player"]["health"] + 1)

    result["player"]["x"] = min(9, max(0, result["player"]["x"] + dx))
    result["player"]["y"] = min(9, max(0, result["player"]["y"] + dy))

    if action["fire"]:
        damage = 1
        if "double" in result["boosts"]:
            result["boosts"].remove("double")
            damage = 2
        for index, target in enumerate(result["targets"]):
            if target["x"] == result["player"]["x"]:
                target["health"] -= damage
                if target["health"] <= 0:
                    result["score"] += target["points"]
                    del result["targets"][index]
                break

    for index, target in enumerate(result["targets"]):
        if target["x"] == result["player"]["x"] and target["y"] == result["player"]["y"]:
            del result["targets"][index]
            result["player"]["health"] -= 1
            break

    if result["player"]["health"] == 0:
        result["player"]["lives"] -= 1
        if result["player"]["lives"] > 0:
            result["player"]["health"] = 3
        else:
            result["ended"] = True
    return result

